import {openAIWizard,localOrigin,attachLocal} from './ai-setup.js?v=20261027-setup1';
import {museum,resources,posts,themes} from './data.js';
import {communities,newCollection,fetchCollectionPage,mergeRows,redact} from './collectors.js?v=20261027-2';
import {levels,assessment,selectRows,cohortScope,groupSignature,templatePlan,fingerprint,validateAssessment} from './domain.js?v=20261027-setup1';
import {loadWorkspace,saveWorkspace,migrate} from './storage.js?v=20261027-2';
import {AIClient} from './ai-client.js?v=20261027-setup1';
import {provenanceCard,highlight} from './evidence-ui.js';
import {safeUrl} from './sources.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=await loadWorkspace().catch(()=>null)||migrate(museum,resources,posts);
state.filters||={};state.assessments||={};state.audit||=[];state.collectionDraft||={source:'hn',query:'museum',from:'',to:''};
let page=location.hash.slice(1)||'overview',tablePage=0,busy=null,controller=null,client=new AIClient(state.backendUrl),connection=null,searchTimer;
const navigation=[['overview','◈','任务总览','Overview'],['social','01','选择数据与获取','Collect'],['analysis','02','分析与五档筛选','Analyze'],['insights','03','需求画像','Audiences'],['studio','04','宣传方案','Marketing'],['dna','▧','博物馆知识库','Museum DNA']];
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4500);}
async function persist(){try{await saveWorkspace(state);}catch{toast('保存失败：可能达到浏览器空间上限。请立即导出工作空间备份。');}}
function go(next){page=next;location.hash=next;tablePage=0;render();window.scrollTo(0,0);}
function badge(t,cls=''){return `<span class="tag ${cls}">${esc(t)}</span>`;}
function action(label,name,primary=false,disabled=false){return `<button data-act="${name}" class="${primary?'primary':''}" ${disabled?'disabled':''}>${label}</button>`;}
function sourceLink(p,label='查看原文 ↗'){const url=safeUrl(p.evidenceUrl||p.sourceUrl);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:'来源未核实';}
const currentRows=()=>selectRows(state,state.filters);
const scope=()=>cohortScope(state,state.filters,state.scopeDays,state.includeHistory);
function levelLabel(a){return !a?'待分析':a.level?levels.find(l=>l.value===a.level).label:a.relevance==='无关'?'无关内容':a.visitState==='已参观/历史反馈'?'历史反馈（不分意愿档）':'信息不足 / 待核实';}
function levelTag(a){return badge(levelLabel(a),a?.level>=4?'teal':a?.level===1?'negative':'');}
function modeName(){return state.mode==='ai'?'真实 AI · '+(connection?.verified?'真实调用已验证':connection?.configured?'配置已填 · 待测试':'待连接模型'):'本地规则演示 · 非 AI';}
function steps(){return `<div class="workflow-steps" aria-label="四步操作流程">${[['social','选择数据与获取'],['analysis','分析与分档'],['insights','需求画像'],['studio','宣传方案']].map(([id,name],i)=>`<a href="#${id}" class="${page===id?'current':''}"><b>${i+1}</b><span>${name}</span><small>${i===0?state.posts.length+' 条已保存':i===1?selectRows(state).filter(r=>r.a).length+' 条有分析':i===2?(state.scopeDays>365?'历史研究窗口':'近期 '+state.scopeDays+' 天'):'按群体生成'}</small></a>`).join('')}</div>`;}
function filters(){const f=state.filters;return `<section class="panel filter-panel"><div class="panel-title"><h3>评论范围 <small>跨页面共享；不受列表分页影响</small></h3>${action('清除全部筛选','clear')}</div><div class="filters"><input id="search" aria-label="搜索评论" placeholder="搜索正文、ID 或话题" value="${esc(f.search||'')}"><select data-filter="source" aria-label="评论来源"><option value="">全部已载入来源</option>${[...new Map(state.posts.map(p=>[p.sourceId||p.source,p.source])).entries()].map(([id,name])=>`<option value="${esc(id)}" ${f.source===id?'selected':''}>${esc(name)}</option>`).join('')}</select><select data-filter="sentiment" aria-label="情绪"><option value="">全部情绪</option>${['正面','负面','中性','混合','不确定'].map(t=>`<option ${f.sentiment===t?'selected':''}>${t}</option>`).join('')}</select><select data-filter="special" aria-label="特殊状态"><option value="">全部意愿状态</option>${[['pending','待分析'],['past','已参观 / 历史反馈'],['irrelevant','无关内容'],['uncertain','待核实']].map(([v,l])=>`<option value="${v}" ${f.special===v?'selected':''}>${l}</option>`).join('')}</select><select data-filter="theme" aria-label="需求主题"><option value="">全部主题</option>${[...themes,'其他'].map(t=>`<option ${f.theme===t?'selected':''}>${t}</option>`).join('')}</select><select data-filter="review" aria-label="人工审核"><option value="">全部审核状态</option>${[['pending','待复核'],['accepted','采用'],['rejected','已排除']].map(([v,l])=>`<option value="${v}" ${f.review===v?'selected':''}>${l}</option>`).join('')}</select><input type="date" data-filter="from" aria-label="评论开始日期" value="${esc(f.from||'')}"><input type="date" data-filter="to" aria-label="评论结束日期" value="${esc(f.to||'')}"></div><div class="level-filters"><span>意愿五档（可多选）</span>${levels.map(l=>`<label class="level-chip"><input type="checkbox" data-level="${l.value}" ${f.levels?.includes(l.value)?'checked':''}>${l.label}</label>`).join('')}</div><p class="muted">情绪与意愿分别判断。已参观、无关和证据不足单列；评分不是到馆概率。${state.mode==='rules'?'当前显示规则演示结果。':'未分析的评论不会被自动判成低意愿。'}</p></section>`;}
function render(){if(!navigation.some(n=>n[0]===page))page='overview';const nav=navigation.find(n=>n[0]===page);$('#app').innerHTML=`<aside><a class="brand" href="#overview"><span class="brand-icon">◈</span><span>MuseRadar <em>AI</em><small>AUDIENCE INTELLIGENCE</small></span></a><div class="workspace-label">需求发现 → 营销验证</div><nav>${navigation.map(n=>`<a href="#${n[0]}" class="${n[0]===page?'active':''}"><span>${n[1]}</span><div>${n[2]}<small>${n[3]}</small></div></a>`).join('')}<a href="./guide.html" target="_blank" rel="noopener noreferrer"><span>?</span><div>完整操作指南 ↗<small>User Guide</small></div></a></nav><div class="sidebar-bottom">真实来源 · 原文可追溯<p>工作空间仅保存在此浏览器</p>${action('连接与运行设置','settings')}</div></aside><div class="shell"><header><div>工作空间 / ${esc(nav[2])}</div><div class="header-right"><span class="museum-name">${esc(state.museum.name)}</span><button data-act="settings" class="status-button">${esc(modeName())}</button></div></header><main><div class="page-heading"><div><div class="eyebrow">MUSERADAR / WORKSPACE 2.0</div><h1>${esc(nav[2])}</h1><p>从真实评论出发，把群体需求转化为有依据的宣传方案。</p></div>${action('连接 AI · 三步向导','settings')}</div>${steps()}<div class="notice"><b>真实评论 · 示例馆资源。</b> 内置 256 条历史评论不代表近期需求；三个在线社区以英文讨论为主，不代表中国博物馆观众。${state.mode==='ai'?'请通过连接向导验证模型；未连接或调用失败不会补造 AI 结果。':'当前为明确标注的本地规则演示模式，不消耗模型 token。'}</div>${busy?`<div class="notice working" role="status"><b>${esc(busy.label)}</b><p>${esc(busy.progress||'正在处理…')}</p>${action('暂停并保留进度','pause')}</div>`:''}${({overview,social,analysis,insights,studio,dna}[page])()}<footer>真实公开评论 · 不保留评论者身份 · 分档不代表到馆概率 <span>MuseRadar AI · Phase 2</span></footer></main></div>`;}
function overview(){const all=selectRows(state),done=all.filter(r=>r.a),high=done.filter(r=>r.a.level>=4&&r.review!=='rejected'),s=scope();return `<section class="hero"><div>${badge('从数据到行动','light')}<h2>让每一种文化需求，<br>找到适合它的博物馆体验。</h2><p>四步完成获取、分析、需求画像与宣传方案。</p>${action(state.tasks.length?'继续我的分析任务 →':'开始一次分析 →','start',true)}</div><div class="radar-art"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><b>◈</b><span class="radar-label l1">真实评论</span><span class="radar-label l2">需求画像</span><span class="radar-label l3">宣传行动</span></div></section><div class="kpis">${[['已保存真实与导入内容',state.posts.length,'条','social'],['当前模式已有分析',done.length,'条','analysis'],['四／五档需求表达',high.length,'条','high'],['近期有效需求群体',s.groups.length,'类','insights']].map(([label,n,unit,target])=>`<button class="kpi" data-go="${target}"><span>${label} ↗</span><strong>${n}<small>${unit}</small></strong><p>点击查看对应范围</p></button>`).join('')}</div><div class="grid2"><section class="panel"><h3>你的下一步</h3><p>${state.tasks.length?'继续已有获取任务，或创建一个新的数据范围。':'先选择一个社区，输入关键词，获取该范围内所有可访问评论。'}</p><div class="toolbar">${action('① 选择与获取评论','start',true)}${action('② 分析与五档筛选','to-analysis')}</div><p class="muted">未准备模型？可先在设置中切换“规则演示”，体验完整交互。AI 模式须配置独立后端。</p></section><section class="panel"><h3>研究数据与近期数据分别使用</h3><p>内置研究快照：256 条 / 4 家博物馆，原始日期 2013—2020 年。</p><p>默认画像窗口：最近 ${state.scopeDays} 天。没有近期样本时保持空结果，不用历史反馈冒充新需求。</p><div class="toolbar">${action('体验历史评论流程','history-demo')}${action('查看博物馆资源','to-dna')}</div></section></div><section class="panel"><h3>已有获取任务</h3>${tasksHTML()||'<p class="muted">尚无在线任务。内置快照不会冒充在线请求。</p>'}</section>`;}
function tasksHTML(){return state.tasks.slice().reverse().map(t=>`<article class="collection-task"><div><strong>${esc(communities.find(s=>s.id===t.source)?.name)} · ${esc(t.query)}</strong> ${badge(({ready:'待开始',running:'获取中',paused:'已暂停',error:'部分获取 / 出错',partial:'部分获取',complete:'已取完可访问结果'})[t.status]||t.status,t.complete&&!t.partialReasons.length?'teal':'')}<p>${esc(t.from||'不限起始')} — ${esc(t.to||t.createdAt.slice(0,10))} · ${t.pages} 次请求 · 响应评论 ${t.received} 条 · 新增 ${t.added} · 重复 ${t.duplicates} · 排除 ${t.excluded}</p><small>${t.source==='hn'?'范围：关键词匹配的索引评论；超窗口时按时间分片':'范围：关键词匹配的问题下的评论；不含回答及其评论'}${t.quota!==undefined?' · 剩余额度 '+t.quota:''}</small>${t.error?`<p class="danger">${esc(t.error)}</p>`:''}${t.partialReasons.length?`<p class="danger">${esc(t.partialReasons.join('；'))}</p>`:''}</div><div>${!t.complete?action('继续 / 重试','resume:'+t.id,true,!!busy):action('查看这些评论','source:'+t.source)}${t.lastUrl?`<a href="${esc(safeUrl(t.lastUrl))}" target="_blank" rel="noopener noreferrer">最近请求 ↗</a>`:''}</div></article>`).join('');}
function social(){const draft=state.collectionDraft;return `<section class="panel"><div class="panel-title"><h3>获取指定范围内全部可访问评论</h3>${badge('自动翻页 · 去重 · 断点保存','teal')}</div><form id="collection-form"><div class="form-grid"><label>公开社区<select name="source" required>${communities.map(s=>`<option value="${s.id}" ${draft.source===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label>关键词<input name="query" value="${esc(draft.query)}" maxlength="200" required></label><label>评论起始日期（可留空）<input name="from" type="date" value="${esc(draft.from)}"></label><label>评论结束日期（可留空）<input name="to" type="date" value="${esc(draft.to)}"></label></div><p class="muted">Travel 和 History 是两个独立社区，使用同一套 Stack Exchange API。先检索相关问题，再取问题下的评论，正文不一定包含关键词；后续需分析相关性。历史数据另保留研究来源。</p><button class="primary" ${busy?'disabled':''}>获取全部可访问结果</button></form></section><section class="panel"><h3>任务与完成情况</h3>${tasksHTML()||'<p class="muted">尚无获取任务。</p>'}<p class="muted">“已取完”仅指公开接口在指定范围内返回的结果；不是全平台覆盖保证。接口限额或中断时显示部分获取。关闭网页后任务暂停，再次打开可继续。</p></section><div class="toolbar">${action('导入 CSV / JSON','import')}${action('载入真实研究快照','samples')}${action('导出筛选评论','export-posts')}${action('下一步：分析与分档 →','to-analysis',true)}</div><input type="file" id="import-file" accept=".csv,.json" hidden>${filters()}${tableHTML()}`;}
function tableHTML(){const rows=currentRows(),pages=Math.max(1,Math.ceil(rows.length/50));tablePage=Math.min(tablePage,pages-1);return `<section class="panel table-panel"><div class="panel-title"><h3>全部筛选结果 <small>${rows.length} 条</small></h3>${badge('仅列表每页 50 条；获取与分析无此限制')}</div><div class="table-scroll"><table><thead><tr><th>来源 / 日期</th><th>原始评论</th><th>意愿 / 情绪</th><th>需求 / 分析方式</th><th>证据与复核</th></tr></thead><tbody>${rows.slice(tablePage*50,(tablePage+1)*50).map(r=>`<tr><td>${esc(r.post.source)}<small>${esc(r.post.date||'日期未知')}</small><small>${esc(r.post.id)}</small></td><td class="body-cell"><button class="comment-open" data-detail="${esc(r.post.id)}">${esc(r.post.text.slice(0,260))}${r.post.text.length>260?'…':''}</button></td><td>${levelTag(r.a)}<small>${esc(r.a?.sentiment||'情绪待分析')}</small></td><td>${esc(r.a?.theme||'待分析')}<small>${r.a?({ai:'真实 AI',rules:'规则演示',human:'人工修正'})[r.a.mode]:'未连接模型或尚未分析'}</small></td><td>${sourceLink(r.post)}<small>${({accepted:'采用',rejected:'已排除',pending:'待复核'})[r.review]}</small><button data-detail="${esc(r.post.id)}">查看 / 修正</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">当前范围没有评论。清除筛选、获取数据或导入文件后重试。</div></td></tr>'}</tbody></table></div><div class="pagination">${action('上一页','prev',false,tablePage===0)}<span>第 ${tablePage+1} / ${pages} 页 · 共 ${rows.length} 条</span>${action('下一页','next',false,tablePage+1>=pages)}</div></section>`;}
function analysis(){const rows=currentRows(),pending=rows.filter(r=>!r.a&&r.review!=='rejected');return `<section class="panel"><div class="panel-title"><h3>情绪分析与参观意愿分开判断</h3>${badge(modeName(),state.mode==='rules'?'':'teal')}</div><p>“上次参观非常开心”是正面历史反馈，不是新的参观计划。地点、时间和活动条件没有证据时，保留不确定性。</p><div class="toolbar">${state.mode==='ai'?action('用 AI 分析当前筛选 '+pending.length+' 条','analyze',true,!!busy||!pending.length):badge('规则演示即时计算；与 AI 结果分开保存')}${action('切换模式 / 连接 AI','settings')}${action('导出全部筛选结果','export-analysis')}${action('下一步：近期需求画像 →','to-insights',true)}</div><p class="muted">AI 使用服务端配置的模型；只处理未完成内容。失败逐条保留原因，支持继续；人工修正不会被自动覆盖。</p></section>${state.aiTask?`<div class="notice">最近分析任务：目标 ${state.aiTask.total} 条 · 成功 ${state.aiTask.success} · 失败 ${state.aiTask.failed} · ${esc(state.aiTask.status)}${Object.keys(state.errors||{}).length?'<details><summary>查看失败原因</summary>'+Object.entries(state.errors).slice(0,20).map(([id,e])=>`<p>${esc(id)}：${esc(e)}</p>`).join('')+'</details>':''}</div>`:''}${filters()}<section class="panel"><form id="test-form"><h3>输入文本测试</h3><label>测试文本（用户输入，不冒充公开评论）<textarea name="text" rows="3" placeholder="请输入需要分析的文本" maxlength="15000" required></textarea></label><button class="primary" ${busy?'disabled':''}>${state.mode==='ai'?'加入数据并用 AI 分析':'加入数据并用规则演示'}</button></form></section>${tableHTML()}`;}
function scopeControls(){return `<section class="panel"><h3>画像与方案使用的数据范围</h3><div class="toolbar"><label>分析窗口 <select id="scope-days">${[[30,'最近 30 天'],[90,'最近 90 天'],[180,'最近半年'],[365,'最近一年'],[6000,'历史研究窗口（约 16 年）']].map(([v,l])=>`<option value="${v}" ${state.scopeDays===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="level-chip"><input type="checkbox" id="include-history" ${state.includeHistory?'checked':''}>纳入历史体验研究（不当作新增观众）</label>${action('清除附加筛选','clear')}</div><p class="muted">沿用全部共享筛选。画像描述共同需求，不推断个人年龄、收入或身份。历史窗口仅用于研究演示。</p></section>`;}
function insights(){const s=scope();return `${scopeControls()}${filters()}<div class="kpis">${[['范围内评论',s.rows.length],['已排除',s.excluded],['尚待分析',s.pending.length],['有效需求分群',s.groups.length]].map(([l,n])=>`<div class="kpi"><span>${l}</span><strong>${n}</strong></div>`).join('')}</div><div class="notice">${s.start} — ${s.end} · ${s.valid.length} 条进入需求分群；无关 ${s.unrelated} 条、待核实 ${s.uncertain} 条、历史反馈 ${s.historical} 条。${state.includeHistory?'当前包含历史体验研究。':'历史反馈默认不进入未来需求画像。'}${s.pending.length?'还有未分析评论，暂不能声称完成整体画像或生成 AI 方案。':'范围内所有未排除评论均已有判断。'}</div><div class="toolbar">${action('AI 分析范围内待处理 '+s.pending.length+' 条','analyze-scope',true,!!busy||state.mode!=='ai'||!s.pending.length)}${action('调整模型与分析方式','settings')}${action('导出画像与完整证据','export-cohorts')}</div><div class="opportunities">${s.groups.map(g=>`<article class="panel"><div class="panel-title">${badge(state.mode==='ai'?'AI / 人工判定后聚合':'规则分群演示','teal')}${badge(g.share+'%')}</div><h3>${esc(g.name)}</h3><p>${g.n} 条 · 四／五档 ${g.high} 条 · 历史 ${g.history} 条 · 来源待核实 ${g.unverified} 条</p><div class="distribution">${g.distribution.map(d=>`<span title="${d.level} 档 ${d.n} 条">${d.level} 档 <b>${d.n}</b></span>`).join('')}</div><p><b>匹配资源</b><br>${state.resources.filter(r=>g.resourceIds.includes(r.id)).map(r=>esc(r.name)).join('、')||'暂无匹配，先完善资源'}</p><blockquote>${esc(g.members[0].post.text.slice(0,230))}</blockquote><p class="muted">共同需求：${esc([...new Set(g.members.flatMap(r=>r.a.needs||[]))].slice(0,8).join('、')||g.theme)}。宣传覆盖待核实。</p><div class="toolbar"><button data-group-view="${esc(g.id)}">查看全部 ${g.n} 条证据</button><button class="primary" data-group-plan="${esc(g.id)}">为此画像制定方案 →</button></div></article>`).join('')||`<div class="panel empty">当前没有有效需求画像。${state.mode==='ai'?'先完成 AI 配置和范围内分析。':'可调整日期、获取近期内容，或体验历史评论研究。'}${action('体验真实历史评论','history-demo')}</div>`}</div>`;}
function studio(){const s=scope(),g=s.groups.find(g=>g.id===state.selectedGroup)||s.groups[0];if(!g)return `${scopeControls()}<section class="panel empty"><h3>先形成一个有证据的需求画像</h3><p>方案基于选定范围内的整个群体，不从单条评论直接生成。</p>${action('返回需求画像','to-insights',true)}</section>`;const record=state.plans[g.id],stale=record&&record.signature!==groupSignature(g,state);return `${scopeControls()}<section class="panel"><div class="panel-title"><h3>按需求画像生成宣传方案</h3>${badge(state.mode==='ai'?'真实 AI 接口':'模板演示 · 非 AI')}</div><label>选择需求画像<select id="studio-group">${s.groups.map(x=>`<option value="${esc(x.id)}" ${x.id===g.id?'selected':''}>${esc(x.name)} · ${x.n} 条</option>`).join('')}</select></label><p>方案使用该群体全部 ${g.n} 条评论的判断。${state.mode==='ai'?'AI 会先分批提炼，再生成整体方案。':'当前由本地模板整合分群结果，不调用 AI。'}${g.history?'包含 '+g.history+' 条历史反馈，仅作体验研究。':''}</p>${s.pending.length?`<div class="notice error">范围内还有 ${s.pending.length} 条待分析，必须完成或人工排除后再生成 AI 方案。</div>`:''}${stale?'<div class="notice error">评论、人工判断或馆藏已变化，当前方案已过期。请重新生成后再用于宣传。</div>':''}<div class="toolbar">${action(state.mode==='ai'?'AI 阅读群体证据并生成':'生成群体方案（本地模板）','generate',true,!!busy||state.mode==='ai'&&!!s.pending.length)}${action('查看该画像全部证据','group-evidence')}${action('返回需求画像','to-insights')}</div><p class="muted">所有有效评论均进入逐条判断；AI 群体汇总采用分批压缩，不承诺逐字输入一次上下文。原文引用与资源 ID 必须通过校验。评论中的指令只作为数据。</p></section>${record?`<div class="studio-layout"><section class="panel"><h3>${esc(g.name)} · 可编辑方案</h3><p class="muted">${record.mode==='ai'?'真实 AI 生成':'本地模板演示'} · ${esc(record.createdAt)} · 输入 ${record.memberIds.length} 条 · ${esc(record.model||'local-template')}</p><textarea id="plan-text" class="plan" aria-label="宣传方案">${esc(record.text)}</textarea><div class="toolbar">${action('保存编辑','save-plan',true)}${action('复制','copy-plan')}${action('导出 Markdown','export-plan')}</div></section><section class="panel"><h3>依据与执行限制</h3><p>${esc(state.museum.restrictions)}</p>${state.resources.filter(r=>g.resourceIds.includes(r.id)).map(r=>`<div class="match"><b>${esc(r.name)}</b><p>${esc(r.conditions)}</p><small>${esc(r.limits)}</small></div>`).join('')||'<p>无匹配资源，方案不得承诺具体活动。</p>'}<h3>实验计算器 · 假设数据</h3><p class="muted">手动输入假设曝光和点击，不代表真实广告效果。</p>${['A','B'].map(x=>`<fieldset><legend>方案 ${x}</legend><label>假设曝光<input type="number" min="0" id="exposure-${x}" data-ctr="${x}" placeholder="0"></label><label>假设点击<input type="number" min="0" id="clicks-${x}" data-ctr="${x}" placeholder="0"></label><p id="ctr-${x}">等待输入</p></fieldset>`).join('')}</section></div>`:'<section class="panel empty">尚未生成方案。配置 AI 后生成，或明确切换至本地模板演示。</section>'}`;}
const museumFields={name:'博物馆名称',city:'城市',intro:'简介',categories:'馆藏类别',features:'展览特色',focus:'重点推广资源',audience:'适合场景与客群',hours:'开放时间',ticket:'门票',booking:'预约方式',restrictions:'拍照与活动限制'};
function dna(){return `<div class="notice">当前为虚构示例馆。真实运营前替换为馆方确认的资料。修改资料后旧 AI 结果标为待重算，已保存方案标为过期。</div><section class="panel"><form id="museum-form"><h3>博物馆资料</h3><div class="form-grid">${Object.entries(museumFields).map(([k,l])=>`<label>${l}<textarea name="${k}" rows="${k==='intro'?3:2}" required>${esc(state.museum[k]||'')}</textarea></label>`).join('')}</div><button class="primary" ${busy?'disabled':''}>保存资料</button></form></section><div class="section-title"><h2>展品与活动 · ${state.resources.length} 项</h2>${action('添加资源','add-resource',true,!!busy)}</div><div class="resource-grid">${state.resources.map(r=>`<article class="panel"><div class="panel-title">${badge(r.type)}<small>${esc(r.id)}</small></div><h3>${esc(r.name)}</h3><p>${esc(r.intro)}</p><p class="muted">${esc(r.keywords)}</p><p>${esc(r.conditions)}</p><p class="muted">限制：${esc(r.limits)}</p><button data-edit-resource="${esc(r.id)}" ${busy?'disabled':''}>编辑资源</button> <button data-delete-resource="${esc(r.id)}" ${busy?'disabled':''}>删除</button></article>`).join('')}</div>`;}
function modal(html,title='详情'){const d=document.createElement('dialog');d.innerHTML=`<div class="modal-head"><h3>${esc(title)}</h3><button data-close aria-label="关闭">×</button></div>${html}`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();return d;}
function showSettings(){if(busy){toast('请先暂停当前任务，再修改分析模式');return;}openAIWizard({modal,client:()=>client,makeClient:(base,token='')=>new AIClient(base,token),apply:async(next,status)=>{client=next;state.backendUrl=next.base;state.activeModel=status.model||'';connection=status;await persist();render();},mode:()=>state.mode,changeMode:async mode=>{state.mode=mode;await persist();render();},backups:()=>action('导出完整工作空间','backup')+action('恢复工作空间备份','restore')+'<input type="file" id="restore-file" accept=".json" hidden><p class="muted">备份包含评论、复核和方案，不含模型密钥或访问令牌。恢复只接收你信任的完整备份。</p>',onReady:()=>{go('analysis');toast('AI 连接已验证，建议先分析少量评论');}});}

function details(id){const post=state.posts.find(p=>p.id===id);if(!post)return;const a=assessment(post,state),review=state.reviews[id]||{};const d=modal(`<div class="tags">${levelTag(a)}${badge(a?.sentiment||'情绪待分析')}${badge(a?({ai:'真实 AI',rules:'规则演示',human:'人工修正'})[a.mode]:'未分析')}</div><blockquote class="evidence">${highlight(post.text,a?.evidence||[])}</blockquote>${provenanceCard(post)}${a?`<h3>判断依据</h3><p>${esc(a.reason)}</p><p>主题：${esc(a.theme)} · 到访状态：${esc(a.visitState)}</p><h3>匹配资源</h3>${state.resources.filter(r=>a.resourceIds?.includes(r.id)).map(r=>`<div class="match"><b>${esc(r.name)}</b><p>${esc(r.conditions)}</p><small>${esc(r.limits)}</small></div>`).join('')||'<p>没有资源匹配，不能承诺具体活动。</p>'}<h3>不确定性</h3><ul>${(a.uncertainties||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="muted">模型 / 方法：${esc(a.model||a.mode)} · ${esc(a.analyzedAt||'人工记录')}</p>`:'<div class="notice">此条尚无有效 AI 分析；可返回批量分析，或在下方人工核实。</div>'}<form id="review-form"><h3>人工审核与修正</h3><label>采用状态<select name="status">${[['pending','待复核'],['accepted','采用'],['rejected','排除（保留原文）']].map(([v,l])=>`<option value="${v}" ${review.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>人工覆盖档位<select name="level"><option value="">保留原分析，不覆盖</option>${levels.map(l=>`<option value="${l.value}">${l.label}</option>`).join('')}<option value="past">历史反馈 / 已参观</option><option value="irrelevant">无关内容</option><option value="uncertain">信息不足 / 待核实</option></select></label><label>修正后的主题<select name="theme">${[...themes,'其他'].map(t=>`<option ${a?.theme===t?'selected':''}>${t}</option>`).join('')}</select></label><label>人工修正证据（必须原文摘录）<textarea name="evidence" rows="2"></textarea></label><label>备注 / 修正理由<textarea name="note" rows="2">${esc(review.note||'')}</textarea></label><p class="muted">对历史评论设未来意愿时，须有原文明示未来需求；每次修改均记录。</p><button class="primary" ${busy?'disabled':''}>保存人工审核</button>${review.override?'<button type="button" id="reset-override">清除人工覆盖</button>':''}</form>`,'评论详情 · '+id);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{if(busy)throw Error('请先暂停当前任务');const f=new FormData(e.target),level=f.get('level'),note=f.get('note').trim(),ev=f.get('evidence').trim();const next={...review,status:f.get('status'),note,at:new Date().toISOString()};if(level){if(!note||!ev||!post.text.includes(ev))throw Error('人工覆盖须填写理由，并摘录一段原文作为证据');const numeric=Number(level);next.override={level:numeric||null,relevance:level==='irrelevant'?'无关':level==='uncertain'?'待核实':'相关',visitState:level==='past'?'已参观/历史反馈':numeric>=4?'未来需求':'未明确',theme:f.get('theme'),sentiment:a?.sentiment||'不确定'};next.fingerprint=fingerprint(post,state.resources,state.museum);next.evidence=[ev];}state.audit.push({id,previous:review,next,at:next.at});state.reviews[id]=next;await persist();d.close();render();toast('审核已保存，画像和方案状态已更新');}catch(e){toast(e.message);}};if(d.querySelector('#reset-override'))d.querySelector('#reset-override').onclick=async()=>{state.audit.push({id,previous:review,action:'reset',at:new Date().toISOString()});state.reviews[id]={status:review.status||'pending'};await persist();d.close();render();};}
function editResource(id){if(busy){toast('请先暂停当前任务');return;}const existing=state.resources.find(r=>r.id===id),r=existing||{id:'R-'+crypto.randomUUID(),type:'活动'},fields={name:'名称',intro:'简介',type:'类型',keywords:'匹配关键词（空格分隔）',scenes:'适合场景',audience:'对应需求群体',conditions:'参与条件',limits:'实际限制'};const d=modal(`<form>${Object.entries(fields).map(([k,l])=>`<label>${l}<textarea name="${k}" rows="2" required>${esc(r[k]||'')}</textarea></label>`).join('')}<button class="primary">保存资源</button></form>`,'馆藏资源');d.querySelector('form').onsubmit=async e=>{e.preventDefault();const value={...r,...Object.fromEntries(new FormData(e.target))};state.resources=existing?state.resources.map(x=>x.id===id?value:x):[...state.resources,value];await persist();d.close();render();toast('资源已更新；旧 AI 分析需要重新计算');};}
async function waitUntil(time,signal){if(time<=Date.now())return;await new Promise((resolve,reject)=>{const abort=()=>{clearTimeout(timer);reject(Error('任务已暂停'));};const timer=setTimeout(()=>{signal?.removeEventListener('abort',abort);resolve();},time-Date.now());signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();});}
async function runCollection(id){if(busy)return;let task=state.tasks.find(t=>t.id===id);controller=new AbortController();busy={kind:'collection',id,label:'正在获取真实评论',progress:''};task.status='running';task.error='';render();try{while(!task.complete){await waitUntil(task.nextRequestAt,controller.signal);const result=await fetchCollectionPage(task,{signal:controller.signal}),clean=mergeRows(result.items,state.posts);state.posts.push(...clean.items);task={...result.task,added:result.task.added+clean.items.length,duplicates:result.task.duplicates+clean.duplicates};state.tasks=state.tasks.map(t=>t.id===id?task:t);await persist();busy.progress=`${task.pages} 次请求 · 新增 ${task.added} 条 · 重复 ${task.duplicates} 条${task.cursor.phase==='search'?' · 正在检索相关问题':''}`;render();if(task.status==='partial'&&!task.complete)break;if(controller.signal.aborted)throw Error('任务已暂停');}toast(task.complete?'已完成所选范围的可访问结果；完整性请查看任务状态':'部分获取，进度已保留');}catch(e){task.status=controller.signal.aborted?'paused':'error';task.error=controller.signal.aborted?'':e.message;state.tasks=state.tasks.map(t=>t.id===id?task:t);await persist();if(task.error)toast(task.error);}finally{busy=null;controller=null;render();}}
async function runAnalysis(rows){if(busy)return;const candidates=rows.filter(r=>!r.a&&r.review!=='rejected');if(!candidates.length){toast('当前范围没有待处理评论');return;}if(state.mode!=='ai'){toast('当前是规则演示；请切换到真实 AI 模式');return;}try{const status=await client.status();connection=status;if(!status.configured)throw Error('后端已连接但尚未配置模型。请稍后在服务端配置。');}catch(e){toast(e.message);return;}
 controller=new AbortController();busy={kind:'analysis',label:'AI 逐批分析',progress:'本次 '+candidates.length+' 条'};state.aiTask={total:candidates.length,success:0,failed:0,status:'运行中',startedAt:new Date().toISOString()};state.errors||={};render();try{for(let i=0;i<candidates.length;i+=5){const batch=candidates.slice(i,i+5),response=await client.analyze(batch.map(r=>r.post),state.resources,state.museum,controller.signal);if(!Array.isArray(response.results))throw Error('AI 后端返回格式无效');for(const r of batch){const result=response.results.find(x=>x.id===r.post.id);try{if(!result||result.error)throw Error(result?.error||'该条未返回结果');const validated=validateAssessment(result.analysis,r.post,state.resources,state.museum);state.assessments[r.post.id]={...validated,model:response.model||result.analysis.model};connection={...connection,verified:true};delete state.errors[r.post.id];state.aiTask.success++;}catch(e){state.errors[r.post.id]=e.message;state.aiTask.failed++;}}busy.progress=`成功 ${state.aiTask.success} / ${candidates.length} · 失败 ${state.aiTask.failed}`;await persist();render();if(controller.signal.aborted)throw Error('任务已暂停');}state.aiTask.status=state.aiTask.failed?'完成（含失败，可重试）':'全部完成';}catch(e){state.aiTask.status=controller.signal.aborted?'已暂停':'中断，可继续';toast(e.message);}finally{await persist();busy=null;controller=null;render();}}
function download(name,data,type='application/json;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function generate(){const s=scope(),g=s.groups.find(x=>x.id===state.selectedGroup)||s.groups[0];if(!g||busy)return;if(state.plans[g.id]&&!confirm('重新生成会覆盖此画像当前已保存的方案，是否继续？'))return;if(state.mode==='rules'){state.plans[g.id]={text:templatePlan(g,state),mode:'rules',createdAt:new Date().toISOString(),signature:groupSignature(g,state),memberIds:g.members.map(r=>r.post.id)};await persist();render();return;}if(s.pending.length){toast('请先完成范围内所有评论的判断或人工排除');return;}try{const status=await client.status();connection=status;if(!status.configured)throw Error('真实 AI 尚未配置；不会用模板冒充 AI 生成');}catch(e){toast(e.message);return;}
 controller=new AbortController();busy={kind:'plan',label:'AI 正在阅读整个需求群体',progress:'先分批提炼，再汇总生成；不会只使用一条评论'};render();try{const summaries=[];for(let i=0;i<g.members.length;i+=12){const batch=g.members.slice(i,i+12).map(r=>({id:r.post.id,text:r.post.text,analysis:r.a}));const data=await client.summary(batch,state.resources,state.museum,controller.signal);summaries.push(data.summary);busy.progress=`已阅读并提炼 ${Math.min(i+12,g.n)} / ${g.n} 条`;render();}const result=await client.plan({id:g.id,name:g.name,n:g.n,history:g.history,unverified:g.unverified,distribution:g.distribution,memberIds:g.members.map(r=>r.post.id)},summaries,state.resources,state.museum,controller.signal);if(typeof result.text!=='string'||!result.text.trim())throw Error('AI 没有返回有效方案');state.plans[g.id]={text:result.text,model:result.model,mode:'ai',signature:groupSignature(g,state),createdAt:new Date().toISOString(),memberIds:g.members.map(r=>r.post.id),summaries};await persist();toast('AI 群体方案已生成，可编辑与导出');}catch(e){toast(controller.signal.aborted?'已暂停生成，原方案保留':e.message);}finally{busy=null;controller=null;render();}}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if(/[\r\n]/.test(c)&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('CSV 引号未闭合');row.push(field);if(row.some(Boolean))rows.push(row);const head=rows.shift()?.map(s=>s.replace(/^\uFEFF/,'').trim());if(!head?.includes('text'))throw Error('CSV 必须有 text 列');return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]||''])));}
async function importFile(file){try{const raw=file.name.toLowerCase().endsWith('.json')?JSON.parse(await file.text()):parseCSV(await file.text());if(!Array.isArray(raw))throw Error('请导入对象数组或 CSV');const errors=[],valid=[];raw.forEach((p,i)=>{if(typeof p.text!=='string'||!p.text.trim()||p.text.length>15000){errors.push('第 '+(i+1)+' 行：text 不能为空，且限 15000 字符');return;}if(p.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!Number.isFinite(Date.parse(p.date))||new Date(p.date).toISOString().slice(0,10)!==p.date)){errors.push('第 '+(i+1)+' 行：日期无效');return;}valid.push({id:'IM-'+crypto.randomUUID(),text:redact(p.text.trim()),date:p.date||'',source:'用户导入（来源未核实）',declaredSource:String(p.source||''),platform:String(p.platform||'用户导入'),kind:'imported',sourceUrl:safeUrl(p.sourceUrl),evidenceUrl:safeUrl(p.evidenceUrl||p.sourceUrl),collectedAt:new Date().toISOString(),provenance:'用户提供，未独立核实；额外身份字段不导入'});});const clean=mergeRows(valid,state.posts),d=modal(`<p>有效新增 ${clean.items.length} 条 · 重复 ${clean.duplicates} 条 · 错误 ${errors.length} 条</p><p class="danger">${errors.slice(0,20).map(esc).join('<br>')}</p>${clean.items.slice(0,5).map(p=>`<blockquote>${esc(p.text)}</blockquote>`).join('')}<button id="commit-import" class="primary" ${clean.items.length?'':'disabled'}>导入有效评论</button>`,'导入预览');d.querySelector('#commit-import').onclick=async()=>{state.posts.push(...clean.items);await persist();d.close();render();toast('已导入；来源核验状态不会因声明而自动升级');};}catch(e){toast(e.message);}}
async function doAction(name){if(name.startsWith('resume:'))return runCollection(name.slice(7));if(name.startsWith('source:')){state.filters={source:name.slice(7)};return go('analysis');}switch(name){case 'start':go('social');break;case 'settings':showSettings();break;case 'to-analysis':go('analysis');break;case 'to-insights':go('insights');break;case 'to-dna':go('dna');break;case 'clear':state.filters={};tablePage=0;await persist();render();break;case 'pause':controller?.abort();break;case 'prev':tablePage--;render();break;case 'next':tablePage++;render();break;case 'analyze':await runAnalysis(currentRows());break;case 'analyze-scope':await runAnalysis(scope().rows);break;case 'history-demo':if(busy){toast('请先暂停当前任务');break;}state.mode='rules';state.scopeDays=6000;state.includeHistory=true;state.filters={};if(!state.posts.some(p=>p.kind==='visitor-review'))state.posts.push(...mergeRows(posts,state.posts).items);await persist();go('insights');toast('历史研究演示：规则模式；不代表近期市场需求');break;case 'import':$('#import-file').click();break;case 'samples':{const clean=mergeRows(posts,state.posts);state.posts.push(...clean.items);await persist();render();toast('新增 '+clean.items.length+' 条真实研究评论，重复 '+clean.duplicates+' 条');break;}case 'export-posts':download('museradar-comments.json',JSON.stringify(currentRows().map(r=>r.post),null,2));break;case 'export-analysis':download('museradar-analysis.json',JSON.stringify(currentRows(),null,2));break;case 'export-cohorts':download('museradar-cohorts.json',JSON.stringify(scope(),null,2));break;case 'add-resource':editResource();break;case 'generate':await generate();break;case 'group-evidence':{const s=scope(),g=s.groups.find(x=>x.id===state.selectedGroup)||s.groups[0];state.filters.theme=g.id;go('analysis');break;}case 'save-plan':{const g=scope().groups.find(x=>x.id===state.selectedGroup)||scope().groups[0];state.plans[g.id].text=$('#plan-text').value;await persist();toast('编辑已保存');break;}case 'copy-plan':try{await navigator.clipboard.writeText($('#plan-text').value);toast('已复制');}catch{$('#plan-text').select();toast('复制权限不可用，已选中文本，请手动复制');}break;case 'export-plan':download('MuseRadar-宣传方案.md',$('#plan-text').value,'text/markdown;charset=utf-8');break;case 'backup':download('MuseRadar-workspace-backup.json',JSON.stringify(state,null,2));break;case 'restore':$('#restore-file').click();break;}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{if(b.matches('a[href^="#"]')){e.preventDefault();go(b.hash.slice(1));return;}if(b.dataset.act)return await doAction(b.dataset.act);if(b.dataset.go){if(b.dataset.go==='high'){state.filters={levels:[4,5]};go('analysis');}else go(b.dataset.go);return;}if(b.dataset.detail)return details(b.dataset.detail);if(b.dataset.editResource)return editResource(b.dataset.editResource);if(b.dataset.deleteResource&&confirm('删除资源后旧 AI 结果需要重新分析。确定删除？')){state.resources=state.resources.filter(r=>r.id!==b.dataset.deleteResource);await persist();render();}if(b.dataset.groupView){state.filters.theme=b.dataset.groupView;go('analysis');}if(b.dataset.groupPlan){state.selectedGroup=b.dataset.groupPlan;await persist();go('studio');}}catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.closest('#collection-form')){state.collectionDraft=Object.fromEntries(new FormData(el.closest('form')));await persist();}if(el.dataset.filter){state.filters[el.dataset.filter]=el.value;tablePage=0;await persist();render();}if(el.dataset.level){const values=new Set(state.filters.levels||[]);el.checked?values.add(+el.dataset.level):values.delete(+el.dataset.level);state.filters.levels=[...values];tablePage=0;await persist();render();}if(el.id==='scope-days'){state.scopeDays=+el.value;await persist();render();}if(el.id==='include-history'){state.includeHistory=el.checked;await persist();render();}if(el.id==='studio-group'){state.selectedGroup=el.value;await persist();render();}if(el.id==='import-file'&&el.files[0])await importFile(el.files[0]);if(el.id==='restore-file'&&el.files[0]){const next=JSON.parse(await el.files[0].text());if(next.version!==3||!Array.isArray(next.posts)||!next.posts.every(p=>typeof p.id==='string'&&typeof p.text==='string'&&typeof p.kind==='string')||!Array.isArray(next.resources)||!next.museum||!Array.isArray(next.tasks)||!next.reviews||!next.assessments||!next.plans||!next.filters||!Array.isArray(next.audit)||!['ai','rules'].includes(next.mode))throw Error('不是完整的 v3 工作空间备份');if(confirm('恢复会替换此浏览器当前工作空间，请先导出备份。继续？')){state=next;state.collectionDraft||={source:'hn',query:'museum',from:'',to:''};state.backendUrl='';client=new AIClient();connection=null;await persist();el.closest('dialog').close();render();toast('已恢复；后端连接需重新设置');}}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){clearTimeout(searchTimer);const pos=el.selectionStart;searchTimer=setTimeout(async()=>{state.filters.search=el.value;tablePage=0;await persist();render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);},250);}if(el.dataset.ctr){const x=el.dataset.ctr,a=+$('#exposure-'+x).value,b=+$('#clicks-'+x).value;$('#ctr-'+x).textContent=a>0&&b>=0&&b<=a?'假设点击率 '+(b/a*100).toFixed(2)+'%':'请输入有效数值：曝光 > 0，0 ≤ 点击 ≤ 曝光';}});
document.addEventListener('submit',async e=>{if(!['collection-form','museum-form','test-form'].includes(e.target.id))return;e.preventDefault();try{if(busy)throw Error('请先完成或暂停当前任务');const f=new FormData(e.target);if(e.target.id==='collection-form'){state.collectionDraft=Object.fromEntries(f);const t=newCollection(state.collectionDraft);state.tasks.push(t);await persist();await runCollection(t.id);}if(e.target.id==='museum-form'){state.museum=Object.fromEntries(f);await persist();render();toast('知识库已更新，旧 AI 分析需重新计算');}if(e.target.id==='test-form'){const text=f.get('text').trim();if(!text)throw Error('请输入非空文本');const p={id:'TEST-'+crypto.randomUUID(),text:redact(text),date:new Date().toISOString().slice(0,10),kind:'manual',source:'手动测试（来源未核实）',collectedAt:new Date().toISOString()};state.posts.push(p);await persist();if(state.mode==='ai')await runAnalysis([{post:p,a:null,review:'pending'}]);render();details(p.id);}}catch(err){toast(err.message);}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';tablePage=0;render();});
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});
for(const t of state.tasks)if(t.status==='running')t.status='paused';
render();

if(localOrigin()){const automatic=new AIClient(localOrigin());attachLocal(automatic).then(async status=>{if(!status)return;client=automatic;connection=status;state.backendUrl=automatic.base;state.activeModel=status.model||'';await persist();render();if(new URL(location.href).searchParams.get('setup')==='1')showSettings();}).catch(()=>{});}
